local _b64=[[]]
local _km={ ((25~28)&255),((91~181)&255),((244~193)&255),((65~27)&255),((36~216)&255),((46~109)&255),((216~25)&255),((255~104)&255),((153~11)&255),((15~158)&255),((160~97)&255),((9~68)&255),((211~139)&255),((105~0)&255),((223~233)&255),((212~173)&255),((237~23)&255),((167~18)&255),((165~180)&255),((59~235)&255),((195~177)&255),((205~65)&255),((148~100)&255),((122~131)&255),((152~24)&255),((233~55)&255),((55~239)&255),((245~84)&255),((200~48)&255),((154~23)&255),((5~57)&255),((234~191)&255) }
local _nm={ ((250~45)&255),((68~253)&255),((18~100)&255),((81~194)&255),((104~239)&255),((166~59)&255),((32~209)&255),((202~97)&255) }
local _cm={ 28,181,193,27,216,109,25,104,11,158,97,68,139,0,233,173,23,18,180,235,177,65,100,131,24,55,239,84,48,23,57,191 }
local _cn={ 45,253,100,194,239,59,209,97 }
local _key={}
local _nonce={}
for i=1,32 do _key[i]=bit32.bxor(_km[i],_cm[i]) end
for i=1,8 do _nonce[i]=bit32.bxor(_nm[i],_cn[i]) end
local _A=bit32
local function _u32(a,b) return _A.band((a+b),0xffffffff) end
local function _rol(x,n) return _A.bor(_A.lshift(x,n),_A.rshift(x,32-n)) end
local function _qr(s,a,b,c,d)
 s[a]=_u32(s[a],s[b]); s[d]=_rol(_A.bxor(s[d],s[a]),16)
 s[c]=_u32(s[c],s[d]); s[b]=_rol(_A.bxor(s[b],s[c]),12)
 s[a]=_u32(s[a],s[b]); s[d]=_rol(_A.bxor(s[d],s[a]),8)
 s[c]=_u32(s[c],s[d]); s[b]=_rol(_A.bxor(s[b],s[c]),7)
end
local function _w(s,i) return s[i]+s[i+1]*256+s[i+2]*65536+s[i+3]*16777216 end
local function _set(s,i,v) s[i]=_A.band(v,255); s[i+1]=_A.band(_A.rshift(v,8),255); s[i+2]=_A.band(_A.rshift(v,16),255); s[i+3]=_A.band(_A.rshift(v,24),255) end
local function _block(counter)
 local s={}
 local c={0x61707865,0x3320646e,0x79622d32,0x6b206574}
 for i=1,8 do c[#c+1]=_w(_key,(i-1)*4+1) end
 c[#c+1]=counter
 c[#c+1]=0
 c[#c+1]=_w(_nonce,1)
 c[#c+1]=_w(_nonce,5)
 for i=1,16 do s[i]=c[i] end
 for _=1,10 do
  _qr(s,1,5,9,13); _qr(s,2,6,10,14); _qr(s,3,7,11,15); _qr(s,4,8,12,16)
  _qr(s,1,6,11,16); _qr(s,2,7,12,13); _qr(s,3,8,9,14); _qr(s,4,5,10,15)
 end
 local o={}
 for i=1,16 do _set(o,(i-1)*4+1,_u32(s[i],c[i])) end
 return o
end
local _alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local _rev={}
for i=1,#_alphabet do _rev[_alphabet:sub(i,i)]=i-1 end
local function _b64dec(x)
 local o={}; local n=0
 for i=1,#x do
  local ch=x:sub(i,i)
  if ch~='=' then n=n*64+_rev[ch]; if i%4==0 then o[#o+1]=_A.band(_A.rshift(n,16),255); o[#o+1]=_A.band(_A.rshift(n,8),255); o[#o+1]=_A.band(n,255); n=0 end end
 end
 local rem=#x%4
 if rem==2 then o[#o+1]=_A.band(_A.rshift(n*16,8),255) elseif rem==3 then o[#o+1]=_A.band(_A.rshift(n*4,8),255); o[#o+1]=_A.band(n*4,255) end
 return o
end
local _enc=_b64dec(_b64)
local _out={}
local _ctr=1
for p=1,#_enc,64 do
 local ks=_block(_ctr); _ctr=_ctr+1
 for j=1,64 do
  local idx=p+j-1; if idx>#_enc then break end
  _out[idx]=string.char(_A.bxor(_enc[idx],ks[j]))
 end
end
local _src=table.concat(_out)
local _load=loadstring or load
assert(_load,_src) (_src)()
